"use client";
import { useRef } from "react";
import { useScrollMotion, type ScrollMotionProps } from "./scroll-shared";
export interface ProgressProps extends ScrollMotionProps {
  variant?: "ring" | "line" | "number";
  size?: number;
  strokeWidth?: number;
  color?: string;
  trackColor?: string;
  showValue?: boolean;
  label?: string;
}
/** Reading progress stays accurate even when reduced motion is enabled. */
export function Progress({
  variant = "ring",
  size = 120,
  strokeWidth = 3,
  color = "currentColor",
  trackColor = "#8883",
  showValue = true,
  label = "Reading progress",
  ...props
}: ProgressProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    props,
    ({ progress: p }) => {
      const el = root.current!;
      el.setAttribute("aria-valuenow", String(Math.round(p * 100)));
      const value = el.querySelector<HTMLElement>("[data-scroll-value]");
      if (value) value.textContent = `${Math.round(p * 100)}%`;
      const ring = el.querySelector<SVGCircleElement>("[data-scroll-ring]");
      if (ring) ring.style.strokeDashoffset = String(1 - p);
      const line = el.querySelector<HTMLElement>("[data-scroll-line]");
      if (line) line.style.transform = `scaleX(${p})`;
    },
    variant,
    true,
    true,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="progress"
      className={props.className}
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round((props.progress ?? 0) * 100)}
      style={{
        position: "relative",
        display: "grid",
        placeItems: "center",
        width: variant === "line" ? "100%" : size,
        height: variant === "line" ? Math.max(28, strokeWidth) : size,
        color,
        ...props.style,
      }}
    >
      {variant === "ring" && (
        <svg
          aria-hidden="true"
          viewBox="0 0 100 100"
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            transform: "rotate(-90deg)",
          }}
          fill="none"
          strokeWidth={Math.min(40, strokeWidth)}
        >
          <circle cx="50" cy="50" r="44" stroke={trackColor} />
          <circle
            data-scroll-ring=""
            cx="50"
            cy="50"
            r="44"
            stroke={color}
            pathLength={1}
            strokeDasharray="1"
            strokeDashoffset={1}
            strokeLinecap="round"
          />
        </svg>
      )}
      {variant === "line" && (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 0,
            height: strokeWidth,
            background: trackColor,
            overflow: "hidden",
          }}
        >
          <div
            data-scroll-line=""
            style={{
              height: "100%",
              background: color,
              transformOrigin: "left",
              transform: "scaleX(0)",
            }}
          />
        </div>
      )}
      {(showValue || variant === "number") && (
        <span
          data-scroll-value=""
          style={{
            fontVariantNumeric: "tabular-nums",
            fontSize: variant === "number" ? size * 0.38 : Math.min(24, size * 0.18),
          }}
        >
          {Math.round((props.progress ?? 0) * 100)}%
        </span>
      )}
    </div>
  );
}

// @zeus-internal
export const scrollClamp = (n: number) => (Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0);
export const scrollLerp = (a: number, b: number, p: number) => a + (b - a) * scrollClamp(p);
export const scrollRange = (value: number, start: number, end: number) =>
  start === end ? Number(value >= end) : scrollClamp((value - start) / (end - start));
export const scrollEase = (p: number) => {
  const q = scrollClamp(p);
  return q * q * (3 - 2 * q);
};
export const scrollStagger = (p: number, index: number, count: number, spread = 0.4) => {
  const s = Math.min(0.95, Math.max(0, spread));
  return scrollClamp((p - (index / Math.max(1, count - 1)) * s) / (1 - s));
};
export const scrollRandom = (index: number, seed = 1) => {
  const x = Math.sin((index + 1) * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
};
export interface ScrollFrame {
  x: number;
  y: number;
  width: number;
  height: number;
  rotation?: number;
  radius?: number;
}
export function scrollFrame(
  frames: readonly ScrollFrame[],
  progress: number,
): Required<ScrollFrame> {
  const p = scrollClamp(progress) * Math.max(0, frames.length - 1),
    index = Math.floor(p);
  const a = frames[index] ?? { x: 0, y: 0, width: 100, height: 100 },
    b = frames[Math.min(index + 1, frames.length - 1)] ?? a;
  return {
    x: scrollLerp(a.x, b.x, p - index),
    y: scrollLerp(a.y, b.y, p - index),
    width: scrollLerp(a.width, b.width, p - index),
    height: scrollLerp(a.height, b.height, p - index),
    rotation: scrollLerp(a.rotation ?? 0, b.rotation ?? 0, p - index),
    radius: scrollLerp(a.radius ?? 0, b.radius ?? 0, p - index),
  };
}
/** Color stops accept CSS hex (3/6 digits) or rgb/rgba. Unknown formats hold until the next stop. */
export function scrollMixColor(a: string, b: string, p: number) {
  const parse = (s: string): number[] | null => {
    const hex = s.replace(/^#/, "");
    if (/^[0-9a-f]{3}$/i.test(hex)) return [...hex].map((x) => parseInt(x + x, 16));
    if (/^[0-9a-f]{6}$/i.test(hex)) return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
    const parts = s
      .match(/^rgba?\(([^)]+)\)$/)?.[1]
      ?.match(/[\d.]+/g)
      ?.map(Number);
    return parts && parts.length >= 3 ? parts : null;
  };
  const ca = parse(a),
    cb = parse(b);
  if (!ca || !cb) return p < 1 ? a : b;
  const channels = [0, 1, 2].map((i) => Math.round(scrollLerp(ca[i]!, cb[i]!, p))).join(", ");
  return ca.length > 3 || cb.length > 3
    ? `rgba(${channels}, ${scrollLerp(ca[3] ?? 1, cb[3] ?? 1, p)})`
    : `rgb(${channels})`;
}

